        for(var entry:byScope.entrySet())if(!entry.getKey().startsWith("cohort:")&&entry.getValue().ids.size()<((Number)policy.get("minimum_cohorts")).intValue()){var s=entry.getValue();entry.setValue(new Subset(s.ids,s.masks.stream().map(m->new MaskResult(m.target,m.variants,null,"Prespecified minimum_cohorts is not met for this scope",m.included,m.exclusions,true)).toList(),false,s.work,s.reused));}
        var rows=new ArrayList<Row>();var sensitivity=new ArrayList<Row>();var diagnostics=new ArrayList<String[]>();var membership=new ArrayList<String[]>();var incomplete=new LinkedHashSet<String>();
        for(var e:byScope.entrySet()){
            String scope=e.getKey();Subset subset=e.getValue();if(!subset.complete)incomplete.add(scope);
            for(var mask:subset.masks){for(String variant:mask.included)membership.add(new String[]{scope,mask.target.set,mask.target.mask,variant,"included"});for(String excluded:mask.exclusions){int tab=excluded.indexOf('\t');membership.add(new String[]{scope,mask.target.set,mask.target.mask,excluded.substring(0,tab),excluded.substring(tab+1)});}
                for(String test:strings(policy.get("tests"))){ConditionalBinarySetTests.Test value=mask.result==null?null:mask.result.tests().stream().filter(t->t.test().equals(test)).findFirst().orElseThrow();String status=!subset.complete?"family_unresolved":value==null?"not_eligible":"ok";double p=value==null?Double.NaN:value.pValue();String calibration=mask.result==null?mask.reason:mask.result.calibration();Row row=new Row(scope,mask.target.set,mask.target.mask,test,"unsigned_set",p,Double.NaN,Double.NaN,"NA",status,String.valueOf(mask.variants),String.valueOf(subset.ids.size()),calibration,"joint_conditional_cohort_strata",test.equals("acat-o")?"canonical_beta_1_25_and_1_1":text(policy.get("weights")));(scope.startsWith("leave-one-out:")?sensitivity:rows).add(row);
                    diagnostics.add(new String[]{scope,mask.target.set,mask.target.mask,test,status,value==null?"NA":number(value.statistic()),number(p),value==null?"NA":number(value.logPValue()),calibration,mask.result==null?"NA":String.valueOf(mask.result.allocationStates()),mask.result==null?"NA":String.valueOf(mask.result.pilotDraws()),mask.result==null?"NA":String.valueOf(mask.result.draws()),value==null?"NA":String.valueOf(value.tailDraws()),mask.result==null?"NA":number(mask.result.pResolution()),value==null?"NA":number(value.tailProbabilityLower95()),value==null?"NA":number(value.tailProbabilityUpper95()),value==null?"NA":String.valueOf(value.constantEvaluatedNull()),mask.reason});
                }
            }
        }
