        List<Row> inference=rows.stream().map(r->incomplete.contains(r.scope())?unresolved(r):r).toList(),sensitivityInference=sensitivity.stream().map(r->incomplete.contains(r.scope())?unresolved(r):r).toList();var adjusted=StudyRareVariants.adjust(inference,adjustment);
        StudyRareVariants.writeResults(c.outputDirectory().resolve("rare-results.tsv"),rows,adjusted,text(policy.get("primary_test")),alpha);StudyRareVariants.writeResults(c.outputDirectory().resolve("rare-primary-results.tsv"),rows.stream().filter(r->r.scope().equals("primary")).toList(),adjusted,text(policy.get("primary_test")),alpha);
